import{_ as t,o,c as s,a2 as n}from"./chunks/framework.7R1OEGYz.js";const p=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"settings.md","filePath":"settings.md","lastUpdated":1793867766000}'),r={name:"settings.md"};function a(i,e,l,c,d,h){return o(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p><strong>Settings</strong> holds everything that belongs to your own account: profile, interface preference, credentials, secrets, MCP servers, skills, notifications, API tokens and webhook triggers. This page is a reference for the <strong>PERSONAL</strong> tabs; most link to a page of their own. Admins also see an <strong>ADMIN</strong> section, described in <a href="/docs/admin">Administration</a>.</p><p><strong>Edition:</strong> Community (Slack notifications: Enterprise) · <strong>Who:</strong> every signed-in user</p><p>Each tab has its own address, such as <code>https://hub.example.com/settings/tokens</code>, so you can bookmark or share a link to it.</p><h2 id="profile" tabindex="-1">Profile <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;Profile&quot;">​</a></h2><p>Your display name, email and the username you are <strong>Signed in as</strong>, with <strong>Sign out</strong>. <strong>About</strong> shows the running Open AgentHub version, with links to the source and the documentation.</p><h3 id="deleting-your-account" tabindex="-1">Deleting your account <a class="header-anchor" href="#deleting-your-account" aria-label="Permalink to &quot;Deleting your account&quot;">​</a></h3><p>The <strong>Danger zone</strong> deletes your account and <strong>all</strong> of its data permanently:</p><ul><li>your sessions, with their pods, browsers, files and stored state,</li><li>credentials, provider logins and git connections,</li><li>skills, MCP servers, usage history and chat links.</li></ul><p>Type your username to confirm, then click <strong>Delete account permanently</strong>. This cannot be undone. Your identity at your OIDC provider is not affected: signing in again starts an empty account.</p><h2 id="interface" tabindex="-1">Interface <a class="header-anchor" href="#interface" aria-label="Permalink to &quot;Interface&quot;">​</a></h2><p>Choose the <strong>Preferred interface</strong> for your sessions and the new-session dialog:</p><ul><li><strong>Workspace</strong>: conversation, tasks and tools in one view (the default). See <a href="/docs/workspace">Workspace</a>.</li><li><strong>Terminal</strong>: the agent&#39;s own console interface.</li></ul><p>Click <strong>Save preference</strong>. The choice is stored in this browser only, so another browser or device starts with Workspace again.</p><h2 id="connected-accounts" tabindex="-1">Connected accounts <a class="header-anchor" href="#connected-accounts" aria-label="Permalink to &quot;Connected accounts&quot;">​</a></h2><p>Connect your GitHub or GitLab account, so sessions can clone and push without a personal access token. The tab only appears when the operator has configured a git provider. See <a href="/docs/git">Git</a>.</p><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to &quot;Credentials&quot;">​</a></h2><p>Provider logins and API keys for the agents, git tokens and your SSH key. Values are write-only: the page only shows whether something is stored. See <a href="/docs/provider-login">Provider login</a> and <a href="/docs/git">Git</a>.</p><h2 id="secrets-mcp-servers-and-skills" tabindex="-1">Secrets, MCP servers and Skills <a class="header-anchor" href="#secrets-mcp-servers-and-skills" aria-label="Permalink to &quot;Secrets, MCP servers and Skills&quot;">​</a></h2><ul><li><strong>Secrets</strong>: named values delivered into sessions as files or environment variables. See <a href="/docs/secrets">Secrets</a>.</li><li><strong>MCP servers</strong>: your personal library of MCP servers for sessions. See <a href="/docs/mcp-servers">MCP servers</a>.</li><li><strong>Skills</strong>: your skill library. See <a href="/docs/skills">Skills</a>.</li></ul><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Shown when</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Desktop notifications</strong></td><td>Always</td><td>Your browser notifies you when a session waits or finishes while the tab is in the background. No server setup needed.</td></tr><tr><td><strong>Telegram notifications</strong></td><td>Telegram is enabled on the instance</td><td>Link your Telegram account or a forum group with a link code, then get session updates and reply from Telegram. See <a href="/docs/chat">Chat</a>.</td></tr><tr><td><strong>Signal notifications</strong></td><td>Signal is enabled on the instance</td><td>Enter your phone number and verify it with a one-time code. See <a href="/docs/chat">Chat</a>.</td></tr><tr><td><strong>Slack notifications</strong></td><td>Slack is enabled (Enterprise)</td><td>A Slack thread when a session waits for input, answered from Slack. By default sent to you directly; a channel can be set instead. See <a href="/docs/slack">Slack</a>.</td></tr></tbody></table><p>If no chat integration is enabled, the tab says so.</p><h2 id="api-tokens" tabindex="-1">API tokens <a class="header-anchor" href="#api-tokens" aria-label="Permalink to &quot;API tokens&quot;">​</a></h2><p>Personal API tokens let scripts and tools start sessions and check their status without the web app, through the remote API (<code>/api/remote/...</code>) or the <a href="/docs/mcp">stdio MCP server</a>. A token starts with <code>oah_</code> and <strong>acts as you</strong>.</p><ol><li>Enter a <strong>Token name</strong> (for example <code>ci-runner</code>) and click <strong>Create token</strong>.</li><li>Copy the token right away. It is shown only once.</li></ol><p>The list shows each token&#39;s name, prefix, restriction, and when it was created and last used. <strong>Delete</strong> asks once more, then stops every client that uses the token. Tokens do not expire; delete the ones you no longer need. <strong>Using a token from the command line</strong> shows example <code>curl</code> calls and an MCP client snippet.</p><h3 id="restricting-a-token" tabindex="-1">Restricting a token <a class="header-anchor" href="#restricting-a-token" aria-label="Permalink to &quot;Restricting a token&quot;">​</a></h3><p>Tick <strong>Restrict to credentials</strong> when creating a token, or click <strong>Restrict</strong> on an existing one. Then tick what sessions created with the token may use:</p><ul><li>provider logins, per agent,</li><li>git tokens,</li><li>secrets delivered into those sessions,</li><li><strong>API keys</strong>: sessions billed to a stored API key.</li></ul><p>Anything left unticked is not available. If nothing is ticked, the token cannot create sessions at all. A session that asks for something outside the restriction is refused. The restriction only governs what a token can bring into a new session. The token can still read, pause and delete your sessions like you can.</p><h2 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h2><p>A webhook trigger starts an <strong>autonomous session</strong> whenever GitHub or GitLab sends a pull request or merge request event, for example a review session for every new merge request.</p><ol><li><p>Under <strong>New webhook trigger</strong>, fill in:</p><ul><li><strong>Name</strong>.</li><li><strong>Git account for cloning</strong> (optional, shown when git providers are configured). Leave empty for public repositories.</li><li><strong>Events</strong>: <code>opened</code> and <code>reopened</code> by default; also <code>updated</code>, <code>closed</code>, <code>merged</code>.</li><li><strong>Repository filter</strong> (optional): part of <code>group/repo</code>. Other repositories are ignored.</li><li><strong>Prompt template</strong>: the session&#39;s prompt. The placeholders below are filled from the event.</li><li><strong>Agent</strong>, and whether to <strong>Auto-approve tool permissions</strong>. See <a href="/docs/auto-approve">Auto approve</a>.</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{{title}}  {{description}}  {{source_branch}}  {{target_branch}}</span></span>
<span class="line"><span>{{url}}  {{repo}}  {{id}}  {{action}}</span></span></code></pre></div></li><li><p>Click <strong>Create webhook</strong>, then copy the URL and the secret. The secret is shown only once; if you lose it, delete the trigger and create a new one.</p></li><li><p>Register the webhook in the repository:</p><ul><li><strong>GitLab</strong>: <strong>Settings → Webhooks</strong>, the URL, the secret as <strong>Secret token</strong>, and <strong>Merge request events</strong> only.</li><li><strong>GitHub</strong>: <strong>Settings → Webhooks</strong>, the URL as <strong>Payload URL</strong>, content type <code>application/json</code>, the secret, and the <strong>Pull requests</strong> event only.</li></ul></li></ol><p>The session checks out the source branch and runs the rendered prompt under your account. Repeated deliveries of the same event are ignored for a few minutes. Other events, other repositories and deliveries that cannot start a session (for example at your session limit or budget) are acknowledged without retry. Each trigger in the list shows when it was <strong>last triggered</strong>.</p><p>This tab only covers incoming triggers. Settings has no outgoing notification webhooks.</p>`,36)])])}const u=t(r,[["render",a]]);export{p as __pageData,u as default};
